//! BZip2 decoder/encoder tests against Python `bz2` oracle fixtures
//! (generated by tests/gen/bzip2.py).
//!
//! Regenerate Rust-encoded fixtures with `BZIP2_REGEN=1 cargo test --test bzip2`,
//! then run `python3 tests/gen/bzip2.py --require-rust` to verify them with
//! Python's bz2.decompress.

use sediment_engine::bzip2_decode::{decode_bzip2, Bzip2DecodeError};
use sediment_engine::bzip2_encode::{encode_bzip2, Bzip2EncodeError};
use std::path::PathBuf;

const WORDS: [&[u8]; 13] = [
    b"the", b"quick", b"brown", b"fox", b"jumps", b"over", b"lazy", b"dog", b"sediment",
    b"archive", b"bzip2", b"block", b"\n",
];

fn lcg(s: u32) -> u32 {
    s.wrapping_mul(1103515245).wrapping_add(12345)
}

fn piece(spec: &str) -> Vec<u8> {
    let p: Vec<&str> = spec.split('.').collect();
    let num = |i: usize| p[i].parse::<usize>().unwrap();
    match p[0] {
        "empty" => Vec::new(),
        "rep" => vec![num(1) as u8; num(2)],
        "seq" => (0..num(1)).map(|i| i as u8).collect(),
        kind => {
            let (mut s, n) = (num(1) as u32, num(2));
            let mut out = Vec::new();
            match kind {
                "lcg" => {
                    for _ in 0..n {
                        s = lcg(s);
                        out.push((s >> 16) as u8);
                    }
                }
                "text" => {
                    while out.len() < n {
                        s = lcg(s);
                        out.extend_from_slice(WORDS[((s >> 16) as usize) % WORDS.len()]);
                        out.push(b' ');
                    }
                }
                "runs" => {
                    while out.len() < n {
                        s = lcg(s);
                        let b = (s >> 16) as u8;
                        s = lcg(s);
                        out.extend(std::iter::repeat_n(b, 1 + ((s >> 16) as usize) % 600));
                    }
                }
                _ => panic!("bad spec {spec}"),
            }
            out.truncate(n);
            out
        }
    }
}

struct Case {
    file: String,
    levels: Vec<u8>,
    input: Vec<u8>,
}

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/bzip2")
}

fn cases() -> Vec<Case> {
    let manifest = std::fs::read_to_string(dir().join("manifest.txt")).unwrap();
    manifest
        .lines()
        .filter(|l| !l.is_empty())
        .map(|line| {
            let (file, desc) = line.split_once(' ').unwrap();
            let mut levels = Vec::new();
            let mut input = Vec::new();
            for st in desc.split(';') {
                let (lv, pieces) = st.split_once(':').unwrap();
                levels.push(lv.parse().unwrap());
                for p in pieces.split(',') {
                    input.extend(piece(p));
                }
            }
            Case { file: file.to_string(), levels, input }
        })
        .collect()
}

fn read(name: &str) -> Vec<u8> {
    std::fs::read(dir().join(name)).unwrap()
}

#[test]
fn decodes_python_fixtures() {
    let cs = cases();
    assert_eq!(cs.len(), 19);
    for c in &cs {
        let data = read(&c.file);
        let got = decode_bzip2(&data, usize::MAX).unwrap_or_else(|e| panic!("{}: {e:?}", c.file));
        assert!(got == c.input, "{} mismatch", c.file);
    }
}

#[test]
fn rust_encoded_fixtures_match_and_roundtrip() {
    let regen = std::env::var_os("BZIP2_REGEN").is_some();
    for c in cases() {
        let enc = encode_bzip2(&c.input, c.levels[0], usize::MAX).unwrap();
        assert_eq!(&enc[..4], &[b'B', b'Z', b'h', b'0' + c.levels[0]]);
        assert_eq!(decode_bzip2(&enc, usize::MAX).unwrap(), c.input, "{}", c.file);
        let path = dir().join(format!("rust_{}", c.file));
        if regen {
            std::fs::write(&path, &enc).unwrap();
        } else {
            let committed = std::fs::read(&path).unwrap_or_else(|_| panic!("missing {path:?}"));
            assert!(
                committed == enc,
                "{path:?} differs from encoder output; regenerate with BZIP2_REGEN=1 and re-verify with tests/gen/bzip2.py"
            );
        }
    }
}

#[test]
fn malformed_fixtures_rejected() {
    use Bzip2DecodeError::*;
    let expect = [
        ("bad_empty.bz2", Truncated),
        ("bad_signature.bz2", BadSignature),
        ("bad_level.bz2", BadSignature),
        ("bad_truncated_header.bz2", Truncated),
        ("bad_truncated_mid.bz2", Truncated),
        ("bad_truncated_end.bz2", Truncated),
        ("bad_block_magic.bz2", BadMagic),
        ("bad_block_crc.bz2", BlockCrcMismatch),
        ("bad_randomized.bz2", Randomized),
        ("bad_stream_crc.bz2", StreamCrcMismatch),
        ("bad_trailing_garbage.bz2", TrailingData),
        ("bad_second_stream.bz2", BadMagic),
    ];
    for (name, err) in expect {
        assert_eq!(decode_bzip2(&read(name), usize::MAX), Err(err), "{name}");
    }
}

#[test]
fn every_truncation_errors() {
    for name in ["run_mix.bz2", "multi_stream.bz2", "one_byte.bz2", "empty_l9.bz2"] {
        let data = read(name);
        for len in 0..data.len() {
            assert!(decode_bzip2(&data[..len], usize::MAX).is_err(), "{name} len {len}");
        }
    }
}

#[test]
fn bit_flips_never_panic() {
    for name in ["run_mix.bz2", "seq_1024.bz2", "one_byte.bz2"] {
        let data = read(name);
        let expected = decode_bzip2(&data, usize::MAX).unwrap();
        let mut d = data.clone();
        for i in 0..d.len() * 8 {
            d[i / 8] ^= 1 << (i % 8);
            // Either an error or (if the flip hit padding) the same output.
            if let Ok(out) = decode_bzip2(&d, 1 << 20) {
                assert_eq!(out, expected, "{name} bit {i}");
            }
            d[i / 8] ^= 1 << (i % 8);
        }
    }
}

#[test]
fn hostile_inputs_bounded() {
    // Header-only garbage and random noise after a valid header.
    let mut s = 99u32;
    for n in [10usize, 50, 200, 2000] {
        for _ in 0..50 {
            let mut d = b"BZh9\x31\x41\x59\x26\x53\x59".to_vec();
            for _ in 0..n {
                s = lcg(s);
                d.push((s >> 16) as u8);
            }
            let _ = decode_bzip2(&d, 1 << 20);
        }
    }
}

#[test]
fn output_cap_enforced() {
    let data = read("zeros_100k_l1.bz2");
    assert_eq!(decode_bzip2(&data, 99_999), Err(Bzip2DecodeError::LimitExceeded));
    assert_eq!(decode_bzip2(&data, 100_000).unwrap().len(), 100_000);
    let data = read("text_50k_l9.bz2");
    assert_eq!(decode_bzip2(&data, 10), Err(Bzip2DecodeError::LimitExceeded));
    assert_eq!(decode_bzip2(&read("empty_l9.bz2"), 0).unwrap(), Vec::<u8>::new());
}

#[test]
fn encoder_levels_and_errors() {
    assert_eq!(encode_bzip2(b"x", 0, usize::MAX), Err(Bzip2EncodeError::InvalidLevel));
    assert_eq!(encode_bzip2(b"x", 10, usize::MAX), Err(Bzip2EncodeError::InvalidLevel));
    assert_eq!(encode_bzip2(b"hello", 9, 10), Err(Bzip2EncodeError::LimitExceeded));
    let empty = encode_bzip2(b"", 9, usize::MAX).unwrap();
    assert_eq!(empty, read("empty_l9.bz2"));
    for level in 1..=9 {
        let input = piece("text.11.20000");
        let enc = encode_bzip2(&input, level, usize::MAX).unwrap();
        assert_eq!(enc[3], b'0' + level);
        assert_eq!(decode_bzip2(&enc, usize::MAX).unwrap(), input);
    }
}

#[test]
fn encoder_block_boundaries() {
    // Incompressible data straddling the level-1 block limit, and run-heavy
    // data whose RLE1 output straddles it.
    for n in [99_980usize, 99_981, 99_982, 100_000, 199_962, 250_000] {
        let input = piece(&format!("lcg.{n}.{n}"));
        let enc = encode_bzip2(&input, 1, usize::MAX).unwrap();
        assert_eq!(decode_bzip2(&enc, usize::MAX).unwrap(), input, "n={n}");
    }
    let mut input = Vec::new();
    let mut s = 5u32;
    while input.len() < 2_000_000 {
        s = lcg(s);
        let b = (s >> 16) as u8;
        s = lcg(s);
        input.extend(std::iter::repeat_n(b, 4 + ((s >> 16) as usize) % 300));
    }
    let enc = encode_bzip2(&input, 1, usize::MAX).unwrap();
    assert_eq!(decode_bzip2(&enc, usize::MAX).unwrap(), input);
}

#[test]
fn encoder_edge_inputs() {
    let mut inputs: Vec<Vec<u8>> = vec![
        vec![0],
        vec![1, 2],
        vec![7; 4],
        vec![7; 255],
        vec![7; 256],
        vec![7; 100_000],
        (0..=255u8).collect(),
        b"abababababababababababab".to_vec(),
        b"banana".to_vec(),
    ];
    // Many distinct MTF symbols, long zero runs, periodic data.
    inputs.push((0..300_000u32).map(|i| (i % 251) as u8).collect());
    inputs.push((0..50_000u32).map(|i| if i % 1000 == 0 { 1 } else { 0 }).collect());
    for input in inputs {
        let enc = encode_bzip2(&input, 9, usize::MAX).unwrap();
        assert_eq!(decode_bzip2(&enc, usize::MAX).unwrap(), input, "len {}", input.len());
    }
}

#[test]
fn concatenated_rust_streams() {
    let a = encode_bzip2(b"first stream ", 3, usize::MAX).unwrap();
    let b = encode_bzip2(b"", 9, usize::MAX).unwrap();
    let c = encode_bzip2(b"second", 1, usize::MAX).unwrap();
    let all = [a, b, c].concat();
    assert_eq!(decode_bzip2(&all, usize::MAX).unwrap(), b"first stream second");
}
